// CommuLingo guided reading (format 'guided-reading'): each lesson shows a
// passage of the site's full translation first, then one question on it, with
// four choices (as in the Engels Ludwig Feuerbach course). Korean passages are
// verbatim from the document marx-gotha-critique (scripts/check-course-source-excerpts.js
// checks them and their anchors). The English passages are translated here from the German
// text the document carries.
// A passage may skip text with ' … '.
// New course 2026-10-31: the Gotha part of the earlier quiz course marx-wages-and-programme, rewritten as guided reading. Every question is new, so the lessons take new ids
// (gotha-critique-chNN-reading) and old quiz answer history is not counted for them.

function t(ko, en) {
    return { ko, en };
}

const DOC = '/commulingo/docs/marx-gotha-critique';
const FROM_ORIGINAL = ' (our translation from the German)';
const TITLE_KO = '『고타강령 비판』';
const TITLE_EN = 'Critique of the Gotha Programme';

const LABELS = {
    'foreword': t(`${TITLE_KO} 엥겔스의 서문(1891)`, `${TITLE_EN}, Engels's foreword of 1891` + FROM_ORIGINAL),
    'bracke': t(`${TITLE_KO} 브라케에게 보낸 편지`, `${TITLE_EN}, letter to Bracke` + FROM_ORIGINAL),
    'appendix': t(`${TITLE_KO} 부록`, `${TITLE_EN}, appendix` + FROM_ORIGINAL),
    'part-1': t(`${TITLE_KO} 제1부`, `${TITLE_EN}, part I` + FROM_ORIGINAL),
    'part-2': t(`${TITLE_KO} 제2부`, `${TITLE_EN}, part II` + FROM_ORIGINAL),
    'part-3': t(`${TITLE_KO} 제3부`, `${TITLE_EN}, part III` + FROM_ORIGINAL),
    'part-4': t(`${TITLE_KO} 제4부`, `${TITLE_EN}, part IV` + FROM_ORIGINAL),
};

function passage(anchor, contextKo, contextEn, quoteKo, quoteEn) {
    return {
        context: t(contextKo, contextEn),
        source: { href: `${DOC}#${anchor}`, label: LABELS[anchor], quote: t(quoteKo, quoteEn) },
    };
}

// Choices and their feedback are authored correct answer first, which is how
// they are stored (answer 0); the player shuffles them for display.
function q(where, koPrompt, enPrompt, koChoices, enChoices, koExplanation, enExplanation, koFeedback, enFeedback) {
    return {
        type: 'multiple_choice',
        points: 0,
        context: where.context,
        prompt: t(koPrompt, enPrompt),
        choices: { ko: koChoices, en: enChoices },
        answer: 0,
        explanation: t(koExplanation, enExplanation),
        choiceFeedback: { ko: koFeedback, en: enFeedback },
        source: where.source,
    };
}

function chapter(ch, anchor, titleKo, titleEn, summaryKo, summaryEn, questions) {
    const id = `gotha-critique-ch${String(ch).padStart(2, '0')}`;
    return {
        id,
        volumeNumber: 18,
        chapterNumber: ch,
        title: t(titleKo, titleEn),
        sourceUrl: `${DOC}#${anchor}`,
        summary: t(summaryKo, summaryEn),
        lessons: [{
            id: `${id}-reading`,
            level: 'basic',
            title: t(titleKo, titleEn),
            questions: questions.map((item, index) => ({ ...item, id: `q${index + 1}`, points: 2 })),
        }],
    };
}

